cd /c/sheep
g(){ node tools/gen.mjs "$@" > /dev/null 2>&1 && echo "done $2" || echo "FAIL $2"; }
g --out art/raw/world/overhang.png --aspect 2048x1152 --bg transparent --quality high --n 3 --ref ref/2b740dbd-0be0-42e5-92bb-1abc9aef6bc9.png --ref ref/c0f6f4b1-4af2-410f-838a-9f2d25a3fa36.png --ref ref/369c595b-d6f6-4f08-9cbb-a2729370ed58.png --prompt "16-bit SNES-era pixel art game layer, same palette and rendering style as the reference game screenshots (Contra / Metal Slug style jungle stage), crisp chunky pixels, dark outlines, no text, no UI, no characters. Draw ONLY an overhanging foreground jungle tree canopy seen from below, hanging DOWN FROM THE TOP EDGE of the image on a fully transparent background: a continuous band of dense dark-green broadleaf foliage and thick mossy branches running along the entire top edge from left to right, with many long hanging vines and moss strands of varying lengths dangling down, like the leaves and vines framing the top of the reference screenshots. Rich saturated greens, darker toward the top, lit leaf edges. The foliage band itself occupies only the top quarter of the image; only the thin vines hang lower. The lower 60% of the image must be completely empty transparent. Nothing else." &
g --out art/raw/world/midtrees.png --aspect 2048x1152 --bg transparent --quality high --n 2 --ref ref/2b740dbd-0be0-42e5-92bb-1abc9aef6bc9.png --ref ref/c0f6f4b1-4af2-410f-838a-9f2d25a3fa36.png --ref ref/369c595b-d6f6-4f08-9cbb-a2729370ed58.png --prompt "16-bit SNES-era pixel art game layer, same palette and rendering style as the reference game screenshots (Contra / Metal Slug style jungle stage), crisp chunky pixels, dark outlines, no text, no UI, no characters. Draw ONLY a sprite sheet of 5 separate tall mid-ground jungle trees on a fully transparent background, well spaced in a row, all standing on the same baseline at the bottom: two tall rainforest trees with thick trunks, big rounded leafy crowns and hanging vines and moss, one cluster of three tall coconut palms of different heights, one tall mossy rock pillar with a tree and ferns on top and vines hanging down its face, and one big banyan-like tree. Slightly blue-hazy mid-distance greens. Nothing else, no ground strip." &
g --out art/raw/world/farcliffs.png --aspect 2048x1152 --bg transparent --quality high --n 2 --ref ref/2b740dbd-0be0-42e5-92bb-1abc9aef6bc9.png --ref ref/c0f6f4b1-4af2-410f-838a-9f2d25a3fa36.png --ref ref/fd55139a-01e5-4131-9ed2-79a9e02c5ecb.png --prompt "16-bit SNES-era pixel art game layer, same palette and rendering style as the reference game screenshots (Contra / Metal Slug style jungle stage), crisp chunky pixels, dark outlines, no text, no UI, no characters. Draw ONLY a wide panoramic range of very distant jungle-topped cliff plateaus on a fully transparent background (no sky): several flat-topped rocky cliff mesas of different heights with thin white waterfalls falling down their faces, all fading into pale blue atmospheric haze toward their bases, soft blue-teal colours, low contrast, far away. The cliffs span the full width edge to edge. Nothing else." &
wait
